Ниже представлен пример программы на C++, которая читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // слово для поиска
    cout << "Введите слово для поиска: ";
    cin >> word;

    string filePath; // путь к файлу
    cout << "Введите путь к файлу: ";
    cin >> filePath;

    // Открытие файла
    ifstream file(filePath);
    if (!file.is_open()) {
        cout << "Ошибка открытия файла: " << filePath << endl;
        return 1;
    }

    int count = 0; // Счетчик вхождений слова

    // Чтение файла построчно
    string line;
    while (getline(file, line)) {
        // Приведение строки к нижнему регистру
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Поиск слова в строке
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    file.close(); // Закрытие файла

    cout << "В файле '" << filePath << "' встречается слово '" << word << "' " << count << " раз(а)." << endl;

    return 0;
}
```

Программа запрашивает у пользователя слово для поиска и путь к текстовому файлу, открывает файл и читает его построчно. Каждая прочитанная строка преобразуется к нижнему регистру, а затем осуществляется поиск введенного слова в строке с помощью метода `find()` класса `string`. При каждом найденном вхождении слово добавляется в счетчик `count`. После завершения чтения файла, программа выводит количество вхождений слова в консоль.
